import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import productService from "../services/productService";
import AOS from "aos";
import "aos/dist/aos.css";
import "./ProductDetail.css";

function ProductDetail() {
    const { id } = useParams();

    const [product, setProduct] = useState(null);
    const [loading, setLoading] = useState(true);
    const [quantity, setQuantity] = useState(1);

    useEffect(() => {
        AOS.init({
            duration: 1000,
            once: true,
            offset: 100,
            easing: "ease-in-out",
        });

        loadProductDetail();

        window.scrollTo({
            top: 0,
            behavior: "smooth",
        });
    }, [id]);

    const loadProductDetail = async () => {
        try {
            setLoading(true);

            const response = await productService.getProductById(id);
            const productData = response.data || response;

            setProduct(productData);

            setTimeout(() => {
                AOS.refresh();
            }, 100);
        } catch (error) {
            console.error("Lỗi khi tải chi tiết sản phẩm:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleQuantityChange = (type) => {
        if (type === "decrease" && quantity > 1) {
            setQuantity(quantity - 1);
        }

        if (type === "increase") {
            setQuantity(quantity + 1);
        }
    };

    if (loading) {
        return (
            <div className="detail-loading">
                <div className="spinner"></div>
                <p>Đang tải thông tin sản phẩm...</p>
            </div>
        );
    }

    if (!product) {
        return (
            <div className="detail-error">
                <h2>Không tìm thấy sản phẩm!</h2>

                <Link to="/shop" className="btn-back">
                    Quay lại cửa hàng
                </Link>
            </div>
        );
    }

    return (
        <div className="product-detail-page">
            <div className="container">

                {/* Breadcrumb */}

                <div
                    className="breadcrumb"
                    data-aos="fade-down"
                >
                    <Link to="/">Trang chủ</Link>

                    <span>/</span>

                    <Link to="/shop">Sản phẩm</Link>

                    <span>/</span>

                    <strong>{product.name}</strong>
                </div>

                {/* TOP SECTION */}

                <div className="detail-top-wrapper">

                    {/* IMAGE */}

                    <div
                        className="detail-image-col"
                        data-aos="fade-right"
                    >
                        <div className="product-badge">
                            SMART FURNITURE
                        </div>

                        <div className="product-image-box">
                            <img
                                src={
                                    product.imageUrl ||
                                    "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85"
                                }
                                alt={product.name}
                                className="product-image-element"
                                onError={(e) => {
                                    e.target.onerror = null;
                                    e.target.src =
                                        "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85";
                                }}
                            />
                        </div>
                    </div>

                    {/* INFO */}

                    <div
                        className="detail-info-col"
                        data-aos="fade-left"
                    >

                        <h1
                            className="product-title"
                            data-aos="fade-left"
                            data-aos-delay="100"
                        >
                            {product.name}
                        </h1>

                        <div
                            className="rating-row"
                            data-aos="fade-left"
                            data-aos-delay="150"
                        >
                            <span className="stars">
                                ⭐⭐⭐⭐⭐
                            </span>

                            <span className="review-count">
                                (25 đánh giá)
                            </span>
                        </div>

                        <div
                            className="product-price-box"
                            data-aos="zoom-in"
                            data-aos-delay="200"
                        >
                            <span className="product-price">
                                {typeof product.price === "number"
                                    ? product.price.toLocaleString(
                                          "vi-VN",
                                          {
                                              style: "currency",
                                              currency: "VND",
                                          }
                                      )
                                    : product.price}
                            </span>
                        </div>

                        <p
                            className="product-short-description"
                            data-aos="fade-up"
                            data-aos-delay="250"
                        >
                            {product.shortDescription ||
                                "Thiết kế tinh tế, chất liệu cao cấp mang lại không gian sống hiện đại và đẳng cấp cho ngôi nhà của bạn."}
                        </p>

                        {/* FEATURES */}

                        <div
                            className="feature-list"
                            data-aos="fade-up"
                            data-aos-delay="300"
                        >
                            <div className="feature-item">
                                ✓ Thiết kế hiện đại
                            </div>

                            <div className="feature-item">
                                ✓ Chất liệu cao cấp
                            </div>

                            <div className="feature-item">
                                ✓ Bảo hành chính hãng
                            </div>

                            <div className="feature-item">
                                ✓ Giao hàng toàn quốc
                            </div>
                        </div>

                        {/* BUY SECTION */}

                        <div
                            className="purchase-action-group"
                            data-aos="fade-up"
                            data-aos-delay="350"
                        >
                            <div className="quantity-selector">
                                <button
                                    type="button"
                                    onClick={() =>
                                        handleQuantityChange("decrease")
                                    }
                                >
                                    −
                                </button>

                                <input
                                    type="number"
                                    value={quantity}
                                    readOnly
                                />

                                <button
                                    type="button"
                                    onClick={() =>
                                        handleQuantityChange("increase")
                                    }
                                >
                                    +
                                </button>
                            </div>

                            <button
                                type="button"
                                className="btn-add-to-cart"
                            >
                                🛒 Thêm vào giỏ hàng
                            </button>
                        </div>

                        {/* META */}

                        <div
                            className="product-meta"
                            data-aos="fade-up"
                            data-aos-delay="450"
                        >
                            <p>
                                <strong>Tình trạng:</strong>{" "}
                                <span className="stock-status">
                                    Còn hàng
                                </span>
                            </p>

                            <p>
                                <strong>Mã sản phẩm:</strong>{" "}
                                SKU-{product.id}
                            </p>

                            <p>
                                <strong>Danh mục:</strong>{" "}
                                Nội thất thông minh
                            </p>
                        </div>

                    </div>
                </div>

                {/* DESCRIPTION */}

                <div
                    className="product-tabs-section"
                    data-aos="fade-up"
                >
                    <div className="tab-header">
                        <h3>Mô tả chi tiết sản phẩm</h3>
                    </div>

                    <div className="tab-content">
                        <p>
                            {product.description ||
                                "Chưa có mô tả chi tiết cho sản phẩm này."}
                        </p>
                    </div>
                </div>

                {/* RELATED PRODUCTS SECTION */}

                <div
                    className="related-products"
                    data-aos="fade-up"
                >
                    <div className="section-title">
